mapper.update:
UPDATE stock_plate
SET active = 0,
    updated_at = CURRENT_TIMESTAMP
WHERE data_source = #{dataSource}
    AND last_seen_trade_date < #{tradeDate}
    AND active = 1

mapper.select:
SELECT COUNT(*)
FROM stock_plate
WHERE data_source = #{dataSource}
    AND last_seen_trade_date = #{tradeDate}
    AND active = 1
